// windowGeometry is every coordinate the terminal-window chrome needs,
// derived once per Encode call from opts. All of it traces back to the
// retired PNG renderer's own constants (image.go's initDefaults/SavePNG, at
// its factor = 2.0): margin 96, padding 48, titleOffset 80, corner radius
// 12, traffic-light radius 18 spaced 50 apart, a 2px window border, and a
// stackblur shadow of radius 32 offset (32, 32). Those numbers are what the
// PNG renderer drew at its own reference em size — a 48px FontSize, backed
// out from the reference renders' fixed 3648×632 canvas (120 columns ×
// ~28px advance + 2×96 margin + 2×48 padding = 3648) — so every one of them
// is scaled here by FontSize/48 to keep the same proportions at this
// package's actual FontSize (16px by default) instead of reproducing the
// PNG renderer's pixel values verbatim.
type windowGeometry struct {
	margin       float64
	padding      float64
	titleOffset  float64
	corner       float64
	trafficR     float64
	trafficGap   float64
	trafficNudge float64
	strokeWidth  float64
	shadowBlur   float64
	shadowOffset float64
}

func newWindowGeometry(opts *Options) windowGeometry {
	scale := opts.FontSize / 48.0

	return windowGeometry{
		margin:       96 * scale,
		padding:      48 * scale,
		titleOffset:  80 * scale,
		corner:       12 * scale,
		trafficR:     18 * scale,
		trafficGap:   50 * scale,
		trafficNudge: 4 * scale,
		strokeWidth:  2 * scale,
		shadowBlur:   32 * scale,
		shadowOffset: 32 * scale,
	}
}

